from absl import flags
import mlxu
import json
from EasyLM.models.llama.llama_train import main as fot_main
from .runner_utils import *
flags.DEFINE_string("config", None, "Path to config file")

FLAGS = flags.FLAGS


def config_from_json():
    with open(FLAGS.config, "r") as f:
        return json.load(f)



def run_fot(_):
    def post_override_callback():
        add_time_to_workdir()
        FLAGS.logger_dir = FLAGS.workdir

    config_dict = config_from_json()
    return run_from_dict(main_fn=fot_main, config_dict=config_dict, post_override_callback=post_override_callback)


if __name__ == "__main__":
    mlxu.run(run_fot)

from easylm import ask, add_provider
from easylm.answer import example_query


def test_example_query():
    response = example_query("What is the capital of France?")
    assert "Paris" in response.content


def test_follow_up():
    response = example_query("What is the capital of France?")
    follow_up = response.reply("What's the population of that city?")
    follow_up_2 = follow_up.reply(
        "Sorry I forgot, what was the name of the country again?"
    )
    assert "France" in follow_up_2.content


def test_default_provider():
    @ask(model="qwen/qwen-2-7b-instruct")
    def calculate(question: str) -> str:
        return f"Calculate this: {question}"

    response = calculate("What is 2 + 2?")
    assert "4" in response.content


def test_add_provider():
    from easylm.config import PROVIDERS_MAP

    add_provider("qwen", "https://qwen.ai/api/v1/chat/completions", "QWEN_API_KEY")
    assert "qwen" in PROVIDERS_MAP

import json
import mlxu
from EasyLM.serving import LMClient


FLAGS, FLAGS_DEF = mlxu.define_flags_with_default(
    input_file='',
    output_file='',
    prefix_field='prefix',
    text_field='text',
    until_field='until',
    eval_type='loglikelihood',
    lm_client=LMClient.get_default_config(),
)


def main(argv):
    lm_client = LMClient(FLAGS.lm_client)
    with mlxu.open_file(FLAGS.input_file, 'r') as fin:
        input_data = json.load(fin)

    if FLAGS.eval_type == 'loglikelihood':
        prefix = input_data[FLAGS.prefix_field]
        text = input_data[FLAGS.text_field]
        loglikelihoods, is_greedys = lm_client.loglikelihood(prefix, text)
        output_data = {
            'loglikelihood': loglikelihoods,
            'is_greedy': is_greedys,
        }
    elif FLAGS.eval_type == 'loglikelihood_rolling':
        text = input_data[FLAGS.text_field]
        loglikelihoods, is_greedys = lm_client.loglikelihood_rolling(text)
        output_data = {
            'loglikelihood': loglikelihoods,
            'is_greedy': is_greedys,
        }
    elif FLAGS.eval_type == 'greedy_until':
        prefix = input_data[FLAGS.prefix_field]
        until = input_data[FLAGS.until_field]
        output_data = {'output_text': lm_client.greedy_until(prefix, until)}
    elif FLAGS.eval_type == 'generate':
        prefix = input_data[FLAGS.prefix_field]
        output_data = {'output_text': lm_client.generate(prefix)}
    else:
        raise ValueError(f'Unknown eval_type: {FLAGS.eval_type}')

    with mlxu.open_file(FLAGS.output_file, 'w') as fout:
        json.dump(output_data, fout)


if __name__ == "__main__":
    mlxu.run(main)

